-- EduNova LOT 17 — Adaptive Study Planner & Academic Orchestration
CREATE TABLE IF NOT EXISTS study_planner_preferences(account_id varchar(64) PRIMARY KEY,timezone varchar(64) NOT NULL DEFAULT 'Africa/Lubumbashi',daily_limit_minutes integer NOT NULL DEFAULT 120,session_max_minutes integer NOT NULL DEFAULT 45,preferred_start_hour integer NOT NULL DEFAULT 18,preferred_end_hour integer NOT NULL DEFAULT 22,buffer_minutes integer NOT NULL DEFAULT 10,weekend_enabled integer NOT NULL DEFAULT 1,row_version integer NOT NULL DEFAULT 1,CHECK(daily_limit_minutes BETWEEN 30 AND 480),CHECK(session_max_minutes BETWEEN 10 AND 120),CHECK(preferred_start_hour BETWEEN 0 AND 23),CHECK(preferred_end_hour BETWEEN 1 AND 24),CHECK(preferred_start_hour < preferred_end_hour),CHECK(buffer_minutes BETWEEN 0 AND 60));
CREATE TABLE IF NOT EXISTS study_planner_busy_blocks(id varchar(64) PRIMARY KEY,account_id varchar(64) NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,label varchar(180) NOT NULL,source varchar(32) NOT NULL DEFAULT 'manual',CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS ix_study_planner_busy_account_time ON study_planner_busy_blocks(account_id,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS study_plan_items(id varchar(64) PRIMARY KEY,account_id varchar(64) NOT NULL,plan_date date NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,course_id varchar(64) NOT NULL,chapter_id varchar(64),action varchar(40) NOT NULL,label varchar(180) NOT NULL,source varchar(24) NOT NULL,priority integer NOT NULL,reason text NOT NULL,expected_outcome text NOT NULL,state varchar(24) NOT NULL DEFAULT 'planned',row_version integer NOT NULL DEFAULT 1,CHECK(ends_at>starts_at),CHECK(priority BETWEEN 0 AND 200),CHECK(state IN ('planned','done','skipped','superseded')),CHECK(source IN ('adaptive','exam','review','error','manual')));
CREATE INDEX IF NOT EXISTS ix_study_plan_account_day_state ON study_plan_items(account_id,plan_date,state,starts_at);
CREATE INDEX IF NOT EXISTS ix_study_plan_course_day ON study_plan_items(account_id,course_id,plan_date);
